import{_ as t,o as r,c as a,l as o}from"./chunks/framework.-NaojeWQ.js";const h=JSON.parse('{"title":"Modern CSS. An honest baseline.","description":"","frontmatter":{},"headers":[],"relativePath":"compatibility.md","filePath":"compatibility.md"}'),d={name:"compatibility.md"};function i(n,e,s,c,l,p){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="modern-css-an-honest-baseline" tabindex="-1">Modern CSS. An honest baseline. <a class="header-anchor" href="#modern-css-an-honest-baseline" aria-label="Permalink to &quot;Modern CSS. An honest baseline.&quot;">​</a></h1><p>The functional benchmark is <strong>iPhone 7 on its latest available iOS 15 update</strong>. The minimum CSS compilation target is Safari 15.4, with Chrome 100 and Firefox 100 as conservative desktop targets. Current Safari, Chrome, Edge and Firefox are intended targets. This does not promise support for an iPhone 7 left on its original iOS 10.</p><p>Apple&#39;s <a href="https://support.apple.com/en-au/100100" target="_blank" rel="noreferrer">security release list</a> identifies the available iPhone 7 updates. We do not infer a Safari patch version from the iOS patch number. <a href="https://webkit.org/blog/12445/new-webkit-features-in-safari-15-4/" target="_blank" rel="noreferrer">WebKit&#39;s Safari 15.4 notes</a> describe relevant feature introductions.</p><h2 id="feature-ledger" tabindex="-1">Feature ledger <a class="header-anchor" href="#feature-ledger" aria-label="Permalink to &quot;Feature ledger&quot;">​</a></h2><p>Every CSS feature family used by the library is recorded below. “Fallback” describes the intended degradation, not evidence of testing on that engine. Release checks and physical-device results belong in the verification section.</p><table tabindex="0"><thead><tr><th>Feature family</th><th>Baseline / compatibility</th><th>Fallback or handling</th></tr></thead><tbody><tr><td>Custom properties, <code>var()</code>, <code>calc()</code></td><td>Supported by iOS 15; required</td><td>No IE support</td></tr><tr><td>Flexbox, gap, wrapping</td><td>Supported by iOS 15</td><td>Wrapped action rows; no fixed desktop-only widths</td></tr><tr><td>Grid, auto-fit/minmax</td><td>Supported by iOS 15</td><td>Single column when space is narrow</td></tr><tr><td>Logical dimensions, margin/padding/border/inset</td><td>Supported by target; compiled with Lightning CSS</td><td>RTL uses logical directions; validate native controls separately</td></tr><tr><td><code>min()</code>, <code>max()</code>, <code>clamp()</code></td><td>Supported by iOS 15</td><td>Bounded sizing; no unbounded viewport typography</td></tr><tr><td><code>:is()</code>, <code>:where()</code>, attribute selectors</td><td>Supported by iOS 15; required for scoped build</td><td>Explicit boundary; low-specificity selectors</td></tr><tr><td><code>:focus-visible</code></td><td>Safari 15.4+</td><td>A standalone <code>:focus</code> outline comes first</td></tr><tr><td><code>:has()</code></td><td>Safari 15.4+</td><td>Enhances checkbox-label layout only; controls retain native operation</td></tr><tr><td>Native <code>dialog</code> / <code>::backdrop</code></td><td>Safari 15.4+</td><td>Older engines need app polyfill or inline content; no automatic polyfill</td></tr><tr><td>Native <code>details</code> / <code>summary</code></td><td>Supported by target</td><td>Browser owns expanded state and keyboard behaviour</td></tr><tr><td><code>accent-color</code></td><td>Safari 15.4+</td><td>Native controls stay usable if accent ignored</td></tr><tr><td>File-selector pseudo-element</td><td>Supported by target; compiler may prefix</td><td>Native file chooser remains usable</td></tr><tr><td>Progress vendor pseudo-elements</td><td>Safari/Firefox rules supplied</td><td>Native progress if custom appearance ignored</td></tr><tr><td><code>color-scheme</code>, dark preference media</td><td>Supported by target</td><td>Light default; explicit theme attributes override system</td></tr><tr><td>HEX / sRGB colour and alpha backdrop</td><td>Supported by target</td><td>Generated static palettes; no <code>color-mix()</code> or OKLCH requirement</td></tr><tr><td>Animations / transforms</td><td>Supported by target</td><td>Reduced-motion media makes busy spinner static</td></tr><tr><td>Forced colours</td><td>Engine-dependent</td><td>System border/focus overrides; macOS contrast differs from Windows forced colours</td></tr><tr><td><code>text-wrap: pretty</code></td><td>Optional newer-browser enhancement</td><td>Ordinary text wrapping</td></tr><tr><td>Overscroll containment</td><td>Optional; support varies in iOS 15</td><td>Native scrolling remains; no interaction depends on containment</td></tr><tr><td>Overflow, sticky sidebar, responsive media</td><td>Supported by target</td><td>Tables scroll locally; sidebar becomes native mobile disclosure</td></tr><tr><td>CSS layers, nesting, <code>@scope</code>, container queries, anchor positioning, popover</td><td>Not runtime dependencies</td><td>Source emits flat selectors; future enhancements must include fallbacks</td></tr></tbody></table><p>Compiled distribution may contain vendor aliases and compatible transformations. Inspect <code>dist/</code> for the actual shipped CSS. Documentation chrome is separate from library CSS and has its own responsive rules.</p><h2 id="javascript-boundary" tabindex="-1">JavaScript boundary <a class="header-anchor" href="#javascript-boundary" aria-label="Permalink to &quot;JavaScript boundary&quot;">​</a></h2><p>The library requires none. The docs use stable VitePress 1.6 and Vue 3.5, built with a Safari 15.4 JS/CSS target. The standalone demo scripts use native modules, DOM APIs and timers available in the target. Clipboard copying is progressive: if unavailable or denied, the generated CSS remains selectable and downloadable.</p><p>The site is statically rendered so documentation content remains available without hydration. The colour studio and local simulations require JavaScript. There are no external font, icon, colour-naming or AI-provider requests.</p><h2 id="verification-record" tabindex="-1">Verification record <a class="header-anchor" href="#verification-record" aria-label="Permalink to &quot;Verification record&quot;">​</a></h2><p>See <a href="/de-gualle/verification.html">verification</a> for checks actually performed. <strong>A 375px viewport or a current WebKit run is not an iPhone 7 test.</strong> No physical-device results are claimed until someone records the device, iOS version, browser and date.</p><h3 id="physical-device-checklist" tabindex="-1">Physical-device checklist <a class="header-anchor" href="#physical-device-checklist" aria-label="Permalink to &quot;Physical-device checklist&quot;">​</a></h3><p>On an updated iPhone 7: load docs and standalone examples; operate all controls with touch; edit multiline text with the keyboard open; send, stop and retry; scroll messages without jumps; rotate; filter a wide table; use dark mode, increased text size, zoom and reduced motion; check VoiceOver labels and announcements. Record failures rather than silently raising the support floor.</p>',14)])])}const m=t(d,[["render",i]]);export{h as __pageData,m as default};
